    _config: routerList[0]._def._config, // Assuming all routers have the same config
    router: true,
    procedures: mergedProcedures,
    queries: mergedQueries,
    mutations: mergedMutations,
    subscriptions: mergedSubscriptions,
    ...emptyRouter,
    record: mergedProcedures,
  };

  const mergedRouter: AnyRouter = {
    ...routerList[0],
    _def,
    createCaller(ctx: TRouters[number]['_def']['_config']['$types']['ctx']) {
      return createCallerFactory<TRouters[number]['_def']['_config']>()(mergedRouter as any)(ctx);
    },
    getErrorShape(opts) {
