function recursiveGetPaths(
  procedures: ProcedureRouterRecord,
  path = '',
  mergedProcedures: ProcedureRecord,
  reservedWordsUsed: Set<string>,
) {
  for (const [key, procedureOrRouter] of Object.entries(procedures ?? {})) {
